PRAGMA foreign_keys = ON;
CREATE TABLE books (id TEXT PRIMARY KEY, title TEXT NOT NULL, author TEXT NOT NULL, file_path TEXT NOT NULL, file_hash TEXT NOT NULL UNIQUE, book_type TEXT NOT NULL DEFAULT 'nonfiction', imported_at INTEGER NOT NULL);
CREATE TABLE chapters (id TEXT PRIMARY KEY, book_id TEXT NOT NULL REFERENCES books(id), idx INTEGER NOT NULL, title TEXT NOT NULL, start_cfi TEXT NOT NULL, end_cfi TEXT NOT NULL, char_count INTEGER NOT NULL, href TEXT NOT NULL, base_cfi TEXT NOT NULL, body_path TEXT NOT NULL, text TEXT NOT NULL, runs_json TEXT NOT NULL, blocks_json TEXT NOT NULL, UNIQUE(book_id,idx));
CREATE TABLE entities (id TEXT PRIMARY KEY, book_id TEXT NOT NULL REFERENCES books(id), type TEXT NOT NULL, name_zh TEXT NOT NULL, name_original TEXT NOT NULL DEFAULT '', aliases_json TEXT NOT NULL, wikidata_qid TEXT, lat REAL, lon REAL, geo_shape TEXT, country TEXT, summary_ext TEXT, image_url TEXT, image_credit TEXT, link_status TEXT NOT NULL DEFAULT 'pending', link_confidence REAL NOT NULL DEFAULT 0, importance REAL NOT NULL, extraction_note TEXT NOT NULL DEFAULT '', candidates_json TEXT NOT NULL DEFAULT '[]', source_chapters_json TEXT NOT NULL, birth TEXT, death TEXT, review INTEGER CHECK(review IN (0,1)), UNIQUE(book_id,type,name_zh));
CREATE TABLE mentions (id TEXT PRIMARY KEY, entity_id TEXT NOT NULL REFERENCES entities(id), chapter_id TEXT NOT NULL REFERENCES chapters(id), cfi_range TEXT NOT NULL, char_offset INTEGER NOT NULL, end_offset INTEGER NOT NULL, is_first_in_chapter INTEGER NOT NULL, is_highlighted INTEGER NOT NULL);
CREATE TABLE glosses (id TEXT PRIMARY KEY, entity_id TEXT NOT NULL REFERENCES entities(id), chapter_id TEXT NOT NULL REFERENCES chapters(id), text TEXT NOT NULL, model TEXT NOT NULL, created_at INTEGER NOT NULL, UNIQUE(entity_id,chapter_id));
CREATE TABLE corrections (id INTEGER PRIMARY KEY, entity_id TEXT NOT NULL REFERENCES entities(id), field TEXT NOT NULL, old_value TEXT, new_value TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE known (book_id TEXT NOT NULL REFERENCES books(id), entity_id TEXT NOT NULL REFERENCES entities(id), PRIMARY KEY(book_id,entity_id));
CREATE TABLE progress (book_id TEXT PRIMARY KEY REFERENCES books(id), current_cfi TEXT NOT NULL, boundary_cfi TEXT NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE conversations (id TEXT PRIMARY KEY, book_id TEXT NOT NULL REFERENCES books(id), messages_json TEXT NOT NULL, archived INTEGER NOT NULL DEFAULT 0, updated_at INTEGER NOT NULL);
CREATE UNIQUE INDEX one_active_conversation ON conversations(book_id) WHERE archived=0;
CREATE TABLE images (id TEXT PRIMARY KEY, entity_id TEXT NOT NULL REFERENCES entities(id), kind TEXT NOT NULL, source TEXT, path TEXT, is_ai INTEGER NOT NULL DEFAULT 0, prompt TEXT, created_at INTEGER NOT NULL);
CREATE TABLE pipeline_jobs (book_id TEXT NOT NULL REFERENCES books(id), step TEXT NOT NULL, chapter_id TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('running','done','failed')), attempts INTEGER NOT NULL, error TEXT, updated_at INTEGER NOT NULL, PRIMARY KEY(book_id,step,chapter_id));
CREATE TABLE extraction_chunks (chapter_id TEXT NOT NULL REFERENCES chapters(id), idx INTEGER NOT NULL, payload_json TEXT NOT NULL, PRIMARY KEY(chapter_id,idx));
CREATE TABLE model_usage (id INTEGER PRIMARY KEY, book_id TEXT NOT NULL REFERENCES books(id), step TEXT NOT NULL, input_tokens INTEGER NOT NULL, output_tokens INTEGER NOT NULL, cache_tokens INTEGER NOT NULL, cost_usd REAL NOT NULL, elapsed_ms INTEGER NOT NULL);
CREATE TABLE wikidata_cache (cache_key TEXT PRIMARY KEY, response_json TEXT NOT NULL, updated_at INTEGER NOT NULL);

CREATE TABLE pipeline_runs (id INTEGER PRIMARY KEY, book_id TEXT NOT NULL REFERENCES books(id), elapsed_ms INTEGER NOT NULL, succeeded INTEGER NOT NULL);
